namespace ghidra.app.plugin.core.function;



using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using generic.theme;
using generic.theme.GThemeDefaults;
using ghidra.app.cmd.function;
using ghidra.app.util;
